<section class="card"><div class="card-head"><div><h2><?= $edit ? 'Edit Donatur' : 'Tambah Donatur' ?></h2><p class="muted">Kelola data donatur. Donatur yang sudah dipakai pada penerimaan tidak dapat dihapus.</p></div><?php if($edit): ?><a class="btn btn-ghost" href="index.php?page=donatur">Batal edit</a><?php endif; ?></div>
<?php if($err): ?><div class="alert alert-err"><?=e($err)?></div><?php endif; ?>
<form method="POST" class="form-grid"><?=csrf_field()?> <input type="hidden" name="form_action" value="<?=$edit?'update':'create'?>"><?php if($edit): ?><input type="hidden" name="id" value="<?=(int)$edit['id']?>"><?php endif; ?>
<label>Nama donatur<input name="nama" maxlength="100" value="<?=e($_POST['nama']??$edit['nama']??'')?>" required></label><label>Jenis donatur<select name="jenis"><option value="individu" <?=((($_POST['jenis']??$edit['jenis']??'individu')==='individu')?'selected':'')?>>Individu</option><option value="lembaga" <?=((($_POST['jenis']??$edit['jenis']??'')==='lembaga')?'selected':'')?>>Lembaga</option></select></label><label>Telepon<input name="telepon" maxlength="20" value="<?=e($_POST['telepon']??$edit['telepon']??'')?>"></label><label>Alamat<input name="alamat" maxlength="255" value="<?=e($_POST['alamat']??$edit['alamat']??'')?>"></label><div class="full"><button class="btn btn-primary" type="submit"><?=$edit?'Simpan Perubahan':'Tambah Donatur'?></button></div></form></section>
<section class="card"><h2>Daftar Donatur</h2><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Jenis</th><th>Telepon</th><th>Alamat</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6" class="empty">Belum ada donatur.</td></tr><?php else: foreach($rows as $r): ?><tr><td><strong><?=e($r['kode'])?></strong></td><td><?=e($r['nama'])?></td><td><?=e(ucfirst($r['jenis']))?></td><td><?=e($r['telepon'])?></td><td><?=e($r['alamat'])?></td><td class="actions"><a class="btn btn-sm btn-warn" href="index.php?page=donatur&action=edit&id=<?=(int)$r['id']?>">Edit</a><form method="POST" data-confirm="Yakin hapus donatur ini? Donatur yang dipakai transaksi tidak dapat dihapus."><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-danger" type="submit">Hapus</button></form></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
